def _find_matching(s: str, start: int) -> int:
    depth = 0
    for i in range(start, len(s)):
        if s[i] == "(":
            depth += 1
        elif s[i] == ")":
            depth -= 1
            if depth == 0:
                return i
    return len(s) - 1


def _fix_polygon_rings(poly_coords: str) -> str:
    # poly_coords includes outer parentheses, eg: "((...),(...))"
    if not poly_coords or poly_coords[0] != "(":
        return poly_coords
    outer_end = _find_matching(poly_coords, 0)
    inside = poly_coords[1:outer_end]
    out_rings = []
    i = 0
    n = len(inside)
    while i < n:
        # skip whitespace and commas
        while i < n and (inside[i].isspace() or inside[i] == ","):
            i += 1
        if i >= n:
            break
        if inside[i] == "(":
            ring_end = _find_matching(inside, i)
            ring_content = inside[i + 1 : ring_end]
            parts = [p.strip() for p in ring_content.split(",") if p.strip()]
            if len(parts) >= 2:
                first = parts[0]
                last = parts[-1]
                if _normalize_coord_string(first) != _normalize_coord_string(last):
                    ring_content = ", ".join(parts + [first])
                else:
                    ring_content = ", ".join(parts)
            else:
                ring_content = ", ".join(parts)
            out_rings.append(f"({ring_content})")
            i = ring_end + 1
        else:
            # unexpected token, copy and continue
            i += 1
    fixed = "(" + ", ".join(out_rings) + ")"
    # append any trailing content after outer_end
    return fixed + poly_coords[outer_end + 1 :]

